// Règles gratuites : lien de désabonnement ou onglet Promotions => newsletter,
// SAUF si l'objet contient un mot important : dans ce cas c'est l'IA qui décide.
const motsImportants = ['rendez-vous', 'rendez vous', 'rdv', 'entretien', 'candidature', 'recrutement', 'convocation',
  'facture', 'commande', 'livraison', 'paiement', 'remboursement', 'reservation', 'confirmation', 'rappel',
  'code', 'securite', 'mot de passe', 'connexion', 'impots', 'banque', 'echeance', 'contrat', 'attestation',
  'examen', 'inscription', 'resultat', 'papier'];
const simplifier = s => (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

const mails = $input.all().map(i => i.json).map(m => {
  const objet = m.subject || m.Subject || '';
  const entetes = JSON.stringify(m.headers || {}).toLowerCase();
  const labels = m.labelIds || [];
  const resteNewsletter = entetes.includes('list-unsubscribe') || labels.includes('CATEGORY_PROMOTIONS');
  const motImportant = motsImportants.some(mot => simplifier(objet).includes(mot));
  return {
    id: m.id,
    de: m.from?.text || m.From || '',
    objet,
    extrait: (m.text || m.snippet || '').replace(/\s+/g, ' ').slice(0, 300),
    categorie: resteNewsletter && !motImportant ? 'newsletter' : null,
  };
});

const aAnalyser = mails
  .filter(m => !m.categorie)
  .map(m => ({ id: m.id, de: m.de, objet: m.objet, extrait: m.extrait }));

return [{ json: { mails, aAnalyser } }];

