// Combine règles + IA et trouve l'ID Gmail de chaque étiquette Tri/...
const { mails } = $('Règles simples').first().json;

let ia = {};
try { ia = JSON.parse($input.first().json.choices[0].message.content); } catch (e) {}

// Comparaison sans majuscules ni espaces : "tri / important" = "Tri/Important"
const norm = s => (s || '').toLowerCase().replace(/\s+/g, '');
const etiquettes = $('Lire les étiquettes').all().map(l => l.json);
const ids = {};
for (const l of etiquettes) ids[norm(l.name)] = l.id;

const noms = { important: 'Tri/Important', newsletter: 'Tri/Newsletter', autre: 'Tri/Autre' };
for (const nom of Object.values(noms)) {
  if (!ids[norm(nom)]) {
    const perso = etiquettes.filter(l => l.type === 'user').map(l => l.name).join(', ');
    throw new Error(`Étiquette Gmail introuvable : ${nom}. Étiquettes trouvées : ${perso || 'aucune'}`);
  }
}

return mails.map(m => {
  const categorie = m.categorie || (['important', 'newsletter', 'autre'].includes(ia[m.id]) ? ia[m.id] : 'important');
  return { json: { categorie, de: m.de, objet: m.objet, id: m.id, labelId: ids[norm(noms[categorie])] } };
});
